package com.optarena.tasktracker;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.jayway.jsonpath.JsonPath;
import com.optarena.tasktracker.repository.ProjectRepository;
import com.optarena.tasktracker.repository.TaskRepository;
import com.optarena.tasktracker.repository.UserRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

@SpringBootTest
@AutoConfigureMockMvc
class BulkAssignCapacityTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private UserRepository userRepository;

    @Autowired
    private ProjectRepository projectRepository;

    @Autowired
    private TaskRepository taskRepository;

    @BeforeEach
    void resetState() {
        userRepository.clear();
        projectRepository.clear();
        taskRepository.clear();
    }

    private int createUser() throws Exception {
        String body = mockMvc.perform(post("/users")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"username\":\"dev\",\"email\":\"dev@example.com\"}"))
                .andReturn().getResponse().getContentAsString();
        return JsonPath.read(body, "$.id");
    }

    private int createProject(int ownerId) throws Exception {
        String body = mockMvc.perform(post("/projects")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"Mercury\",\"ownerId\":" + ownerId + "}"))
                .andReturn().getResponse().getContentAsString();
        return JsonPath.read(body, "$.id");
    }

    private int createTask(int projectId, String title) throws Exception {
        String body = mockMvc.perform(post("/tasks")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\",\"projectId\":" + projectId + "}"))
                .andReturn().getResponse().getContentAsString();
        return JsonPath.read(body, "$.id");
    }

    @Test
    void bulkAssignRejectsWholeBatchWhenCumulativeExceedsCapacity() throws Exception {
        int userId = createUser();
        int projectId = createProject(userId);
        int t1 = createTask(projectId, "A");
        int t2 = createTask(projectId, "B");
        int t3 = createTask(projectId, "C");
        int t4 = createTask(projectId, "D");

        mockMvc.perform(post("/tasks/bulk-assign")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"taskIds\":[" + t1 + "," + t2 + "," + t3 + "," + t4
                                + "],\"assigneeId\":" + userId + "}"))
                .andExpect(status().isConflict());

        String t1Body = mockMvc.perform(get("/tasks/" + t1))
                .andReturn().getResponse().getContentAsString();
        Object assigneeId = JsonPath.read(t1Body, "$.assigneeId");
        assertThat(assigneeId).isNull();
    }

    @Test
    void bulkAssignSucceedsWithinCapacity() throws Exception {
        int userId = createUser();
        int projectId = createProject(userId);
        int t1 = createTask(projectId, "A");
        int t2 = createTask(projectId, "B");

        mockMvc.perform(post("/tasks/bulk-assign")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"taskIds\":[" + t1 + "," + t2 + "],\"assigneeId\":" + userId + "}"))
                .andExpect(status().isOk());
    }
}

