package com.optarena.tasktracker.controller;

import com.optarena.tasktracker.dto.TaskBulkAssignRequest;
import com.optarena.tasktracker.dto.TaskCreateRequest;
import com.optarena.tasktracker.dto.TaskResponse;
import com.optarena.tasktracker.dto.TaskUpdateRequest;
import com.optarena.tasktracker.exception.ConflictException;
import com.optarena.tasktracker.exception.NotFoundException;
import com.optarena.tasktracker.model.Task;
import com.optarena.tasktracker.model.TaskStatus;
import com.optarena.tasktracker.repository.TaskRepository;
import com.optarena.tasktracker.repository.UserRepository;
import com.optarena.tasktracker.service.TaskService;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PatchMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class TaskController {
    private static final int MAX_ACTIVE_TASKS_PER_ASSIGNEE = 3;

    private final TaskService taskService;
    private final TaskRepository taskRepository;
    private final UserRepository userRepository;

    public TaskController(TaskService taskService, TaskRepository taskRepository, UserRepository userRepository) {
        this.taskService = taskService;
        this.taskRepository = taskRepository;
        this.userRepository = userRepository;
    }

    @PostMapping("/tasks")
    @ResponseStatus(HttpStatus.CREATED)
    public TaskResponse createTask(@RequestBody TaskCreateRequest request) {
        return TaskResponse.from(taskService.createTask(request));
    }

    @PostMapping("/tasks/bulk-assign")
    public List<TaskResponse> bulkAssignTasks(@RequestBody TaskBulkAssignRequest request) {
        if (userRepository.findById(request.assigneeId()).isEmpty()) {
            throw new NotFoundException("assignee not found");
        }
        if (request.taskIds() == null || request.taskIds().isEmpty()) {
            throw new ConflictException("taskIds must not be empty");
        }

        List<Task> tasks = request.taskIds().stream()
                .map(id -> taskRepository.findById(id)
                        .orElseThrow(() -> new NotFoundException("task not found: " + id)))
                .toList();

        long current = taskRepository.countActiveForAssignee(request.assigneeId());
        if (current + tasks.size() > MAX_ACTIVE_TASKS_PER_ASSIGNEE) {
            throw new ConflictException("batch would exceed assignee's maximum active tasks");
        }

        for (Task task : tasks) {
            task.setAssigneeId(request.assigneeId());
            taskRepository.save(task);
        }
        return tasks.stream().map(TaskResponse::from).toList();
    }

    @GetMapping("/tasks")
    public List<TaskResponse> listTasks(
            @RequestParam(required = false) Long projectId,
            @RequestParam(required = false) TaskStatus status,
            @RequestParam(required = false) Long assigneeId,
            @RequestParam(defaultValue = "0") int skip,
            @RequestParam(defaultValue = "100") int limit
    ) {
        return taskService.listTasks(projectId, status, assigneeId, skip, limit).stream()
                .map(TaskResponse::from).toList();
    }

    @GetMapping("/tasks/{taskId}")
    public TaskResponse getTask(@PathVariable Long taskId) {
        return TaskResponse.from(taskService.getTask(taskId));
    }

    @PatchMapping("/tasks/{taskId}")
    public TaskResponse updateTask(@PathVariable Long taskId, @RequestBody TaskUpdateRequest request) {
        return TaskResponse.from(taskService.updateTask(taskId, request));
    }

    @DeleteMapping("/tasks/{taskId}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void deleteTask(@PathVariable Long taskId) {
        taskService.deleteTask(taskId);
    }
}

